create table RB_CONTROL_TYPE_DEF (CONTROL_TYPE VARCHAR(3) not null  ,CONTROL_TYPE_DESC VARCHAR(200) null  ,CTL_TYPE VARCHAR(1) null  ,CHANNEL_MUSTER VARCHAR(200) null  ,CONTROL_CLASS VARCHAR(5) not null  ,MANUAL_CTRL_FLAG VARCHAR(1) null  ,MANUAL_UN_CTRL_FLAG VARCHAR(1) null  ,COMPANY VARCHAR(20) null  ,TRAN_TIMESTAMP VARCHAR(26) null  , primary key(CONTROL_TYPE,CONTROL_CLASS));